def get_items():
    return [bc.make_item(*x) for x in EXTRA_COMIDA]

def get_new_items():
    existing = bc.get_existing_names_for_theme('Comida')
    pool_cand = pbfc.get_comida_items()
    all_cand = get_items() + pool_cand
    
    seen = set()
    unique_new = []
    for x in all_cand:
        name = bc.get_item_name(x)
        norm = bc.normalize_name(name)
        if norm not in existing and norm not in seen:
            seen.add(norm)
            unique_new.append(x)
    return unique_new
